NAVY=colors.HexColor('#142846'); BLUE=colors.HexColor('#2f6de0'); PALE=colors.HexColor('#eaf1ff'); INK=colors.HexColor('#25354b'); MUTED=colors.HexColor('#607087'); LINE=colors.HexColor('#d9e2ef'); GREEN=colors.HexColor('#19845b')
PW,PH=A4; M=18*mm; CW=PW-2*M
S=getSampleStyleSheet()
S.add(ParagraphStyle(name='CB',parent=S['Normal'],fontName='Helvetica-Bold',fontSize=10,leading=14,textColor=BLUE,alignment=1))
S.add(ParagraphStyle(name='CM',parent=S['Normal'],fontSize=8,leading=11,textColor=MUTED,alignment=1))
