S.add(ParagraphStyle(name='HeadR',parent=S['BodyText'],fontName='Helvetica-Bold',fontSize=7.4,leading=9,textColor=colors.white))
S.add(ParagraphStyle(name='Call',parent=S['BodyText'],fontName='Helvetica-Bold',fontSize=8,leading=10,textColor=BLUE))
S.add(ParagraphStyle(name='Cap',parent=S['BodyText'],fontName='Helvetica-Oblique',fontSize=7.1,leading=9,textColor=MUTED,alignment=1,spaceAfter=4))
S.add(ParagraphStyle(name='CodeR',parent=S['Code'],fontName='Courier',fontSize=7,leading=9,backColor=colors.HexColor('#f3f6fa'),borderColor=LINE,borderWidth=.4,borderPadding=7,leftIndent=5,rightIndent=5,spaceBefore=3,spaceAfter=5))
def p(t,sty='BR'): return Paragraph(t,S[sty])
def table(rows,widths,header=True):
    d=[[p(str(v),'HeadR' if header and ri==0 else 'CellR') for v in row] for ri,row in enumerate(rows)]
    cmds=[('GRID',(0,0),(-1,-1),.4,LINE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5),('ROWBACKGROUNDS',(0,1 if header else 0),(-1,-1),[colors.white,colors.HexColor('#f7f9fc')])]
    if header: cmds.append(('BACKGROUND',(0,0),(-1,0),BLUE))
    return Table(d,colWidths=widths,repeatRows=1 if header else 0,style=TableStyle(cmds),hAlign='LEFT')
def callout(title,text):
    t=Table([[p(title.upper(),'Call')],[p(text,'SM')]],colWidths=[CW-8*mm])
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),PALE),('BOX',(0,0),(-1,-1),.4,LINE),('LINEBEFORE',(0,0),(0,-1),2.5,BLUE),('LEFTPADDING',(0,0),(-1,-1),7*mm),('RIGHTPADDING',(0,0),(-1,-1),4*mm),('TOPPADDING',(0,0),(-1,0),6),('BOTTOMPADDING',(0,0),(-1,0),1),('TOPPADDING',(0,1),(-1,1),1),('BOTTOMPADDING',(0,1),(-1,1),6)]))
    return t
class Arch(Flowable):
    def __init__(self): super().__init__(); self.width=CW; self.height=76*mm
    def draw(self):
        c=self.canv; w=self.width; h=self.height; c.setFillColor(colors.HexColor('#f7f9fc')); c.roundRect(0,0,w,h,5,fill=1,stroke=0)
        items=[('Retail user','Browser UI',BLUE),('React + Vite','Frontend modules',BLUE),('Spring Boot','REST controllers',NAVY),('Spring Data JPA','Repositories',NAVY),('PostgreSQL','Configured target',GREEN)]
        bw=27*mm; gap=(w-24*mm-5*bw)/4; y=27*mm
        for i,(a,b,col) in enumerate(items):
            x=12*mm+i*(bw+gap); c.setFillColor(colors.white); c.setStrokeColor(LINE); c.roundRect(x,y,bw,22*mm,4,fill=1,stroke=1); c.setFillColor(col); c.setFont('Helvetica-Bold',7); c.drawCentredString(x+bw/2,y+14*mm,a); c.setFillColor(MUTED); c.setFont('Helvetica',6.3); c.drawCentredString(x+bw/2,y+8*mm,b)
            if i<4:
                x2=x+bw; x3=x+bw+gap; c.setStrokeColor(BLUE); c.line(x2+1*mm,y+11*mm,x3-2*mm,y+11*mm); c.line(x3-4*mm,y+12.5*mm,x3-2*mm,y+11*mm); c.line(x3-4*mm,y+9.5*mm,x3-2*mm,y+11*mm)
        c.setFont('Helvetica-Oblique',6.8); c.setFillColor(MUTED); c.drawCentredString(w/2,10*mm,'JSON REST requests connect the user interface to persisted inventory records.')
class ER(Flowable):
    def __init__(self): super().__init__(); self.width=CW; self.height=75*mm
    def draw(self):
        c=self.canv; w=self.width; c.setFillColor(colors.HexColor('#f7f9fc')); c.roundRect(0,0,w,self.height,5,fill=1,stroke=0)
        specs=[('PRODUCT',['id (PK)','sku (unique)','name, category','price, description','quantity, minStock']),('STOCK_TRANSACTION',['id (PK)','productId (scalar ref)','productName snapshot','type, quantity','transactionDate']),('SUPPLIER',['id (PK)','name','contact','email, phone'])]
        bw=44*mm; xs=[10*mm,(w-bw)/2,w-bw-10*mm]; y=17*mm
        for (title,fields),x in zip(specs,xs):
            bh=47*mm; c.setFillColor(colors.white); c.setStrokeColor(LINE); c.roundRect(x,y,bw,bh,4,fill=1,stroke=1); col=GREEN if title=='SUPPLIER' else BLUE; c.setFillColor(col); c.roundRect(x,y+bh-9*mm,bw,9*mm,4,fill=1,stroke=0); c.rect(x,y+bh-9*mm,bw,4*mm,fill=1,stroke=0); c.setFillColor(colors.white); c.setFont('Helvetica-Bold',7.5); c.drawCentredString(x+bw/2,y+bh-6*mm,title); c.setFillColor(INK); c.setFont('Helvetica',6.7)
            for i,f in enumerate(fields): c.drawString(x+3*mm,y+bh-15*mm-i*5.5*mm,f)
        x1=xs[0]+bw; x2=xs[1]; c.setStrokeColor(BLUE); c.line(x1,40*mm,x2,40*mm); c.line(x2-2*mm,41.5*mm,x2,40*mm); c.line(x2-2*mm,38.5*mm,x2,40*mm); c.setFont('Helvetica-Oblique',6); c.setFillColor(MUTED); c.drawCentredString((x1+x2)/2,43*mm,'ID reference; no FK constraint'); c.drawCentredString(w/2,7*mm,'Suppliers are not currently associated with products.')
def decorate(c,doc):
    c.saveState()
    if doc.page>1:
        c.setStrokeColor(BLUE); c.setLineWidth(.6); c.line(M,PH-15*mm,PW-M,PH-15*mm); c.setFillColor(NAVY); c.setFont('Helvetica-Bold',7); c.drawRightString(PW-M,PH-12*mm,'RIMS  |  PROJECT SUBMISSION')
    c.setStrokeColor(LINE); c.line(M,14*mm,PW-M,14*mm); c.setFillColor(MUTED); c.setFont('Helvetica',7); c.drawString(M,9.5*mm,'Jasmeet Singh  |  XYZ Retail Corporation  |  PRG_RIMS_001'); c.drawRightString(PW-M,9.5*mm,str(doc.page)); c.restoreState()
def screenshot(title,lead,name,caption,calltitle,note):
    im=Image(str(ROOT/'screenshots'/name),width=CW,height=CW*1000/1440); im.hAlign='CENTER'
    return [p(title,'H1R'),p(lead),Spacer(1,2*mm),im,p(caption,'Cap'),callout(calltitle,note),PageBreak()]

