hero=Table([[p('RETAIL INVENTORY<br/>MANAGEMENT SYSTEM','CT')],[p('A practical workspace for catalog, inventory, supplier and reporting operations','CS')]],colWidths=[CW],rowHeights=[37*mm,19*mm],style=TableStyle([('BACKGROUND',(0,0),(-1,-1),NAVY),('LEFTPADDING',(0,0),(-1,-1),10*mm),('RIGHTPADDING',(0,0),(-1,-1),10*mm),('TOPPADDING',(0,0),(-1,-1),5*mm),('BOTTOMPADDING',(0,0),(-1,-1),3*mm)]))
