meta=[['LEARNER NAME','Jasmeet Singh','PROJECT CODE','PRG_RIMS_001'],['CLIENT','XYZ Retail Corporation','DOMAIN','Retail Inventory Management'],['PROGRAMME','Individual Project','FORMAT','Full-stack Web Application'],['TECHNOLOGY','React, Spring Boot, PostgreSQL','REPORT DATE','30 October 2026']]
