mt=Table(md,colWidths=[26*mm,61*mm,26*mm,CW-113*mm],style=TableStyle([('BACKGROUND',(0,0),(0,-1),BLUE),('BACKGROUND',(2,0),(2,-1),BLUE),('BACKGROUND',(1,0),(1,-1),colors.HexColor('#f2f5fa')),('BACKGROUND',(3,0),(3,-1),colors.HexColor('#f2f5fa')),('GRID',(0,0),(-1,-1),.4,colors.white),('VALIGN',(0,0),(-1,-1),'MIDDLE'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8)]))
