story += [p('4. Technology Stack and Project Structure','H1R'),table([['LAYER','TECHNOLOGY','ROLE'],['Frontend','React, Vite, JavaScript','Responsive module interface and production bundling.'],['HTTP / icons','Axios, Lucide React','REST communication and interface icons.'],['Backend','Java 17, Spring Boot 3.3, Spring Web','REST endpoints and application startup.'],['Persistence','Spring Data JPA / Hibernate','Entity persistence and schema generation.'],['Database','PostgreSQL 16; H2 local fallback','Relational target and local development store.'],['Packaging','Maven, Docker Compose','Java build and database/backend containers.'],['Reporting','ReportLab, Python','Generation of this academic report.']],[29*mm,54*mm,CW-83*mm]),p('4.1 Workspace organization','H2R'),Preformatted('.\n+-- backend/              Spring Boot Maven service\n|   +-- src/main/java/   Entities, repositories, controller, seed data\n|   +-- src/main/resources/application.properties\n+-- frontend/             React + Vite application\n|   +-- src/main.jsx      Modules and UI interactions\n|   +-- src/styles.css    Responsive styling\n+-- docs/                  Architecture diagrams\n+-- screenshots/           Captured application screens\n+-- report/                PDF generation source\n+-- output/pdf/             Final project report\n+-- .env.example            Configuration template\n+-- docker-compose.yml      PostgreSQL and backend services\n+-- README.md               Setup and API documentation',S['CodeR']),p('4.2 Configuration overview','H2R'),p('`VITE_API_URL` sets the frontend API base URL. `SPRING_DATASOURCE_URL`, `SPRING_DATASOURCE_USERNAME`, and `SPRING_DATASOURCE_PASSWORD` configure the backend datasource. Compose points the backend container to the PostgreSQL service.'),PageBreak()]

# 5 Database
story += [p('5. Database Design and Implementation','H1R'),p('5.1 Entity relationship overview','H2R'),ER(),p('Figure 2. Implemented persistence fields and the scalar product reference recorded on stock transactions.','Cap'),p('5.2 Entity summary','H2R'),table([['ENTITY','KEY FIELDS','NOTES'],['Product','id, sku, name, category, price, description, quantity, minStock','SKU is unique; quantity and threshold are stored on the product.'],['StockTransaction','id, productId, productName, type, quantity, transactionDate','Product ID is a scalar reference, not an enforced foreign key. Product name is retained as a snapshot.'],['Supplier','id, name, contact, email, phone','Supplier directory is independent of products.']],[35*mm,69*mm,CW-104*mm]),p('5.3 Database behavior','H2R'),p('Hibernate updates the schema from the entity model. On a clean database, seed data inserts four example products and two supplier records. File-backed H2 preserves local data across normal refreshes and restarts. PostgreSQL is configured in Docker Compose but was not started during this verification.'),callout('Relationship limitation','The diagram shows the product ID reference held by transaction history. There is no JPA relationship or database foreign key at present. Supplier records are not linked to products.'),PageBreak()]

