story += [p('6. Functional Modules','H1R'),p('6.1 Dashboard','H2R'),p('Shows product count, total on-hand units, estimated retail inventory value, low-stock count, category quantity bars, and recent transaction rows. Values come from the backend while the API is available.'),p('6.2 Product and inventory management','H2R'),p('The catalog searches by product name, SKU, and category in the interface; the backend supports name/SKU search. Inventory view compares quantity to minimum stock and offers stock movement entry.'),p('6.3 Supplier management','H2R'),p('Supplier cards show name, contact person, email, and phone. The backend exposes supplier CRUD. Supplier-to-product assignment is not implemented.'),p('6.4 Stock transaction history','H2R'),p('A transaction request identifies product, movement (`IN` or `OUT`), and quantity. A stock-out that exceeds availability is rejected. A successful movement updates product quantity and creates a timestamped history record.'),p('6.5 Reports','H2R'),p('Reports displays an inventory summary and a CSV export action. The backend route returns SKU, product name, category, price, quantity, minimum stock, and stock status.'),PageBreak()]

