story += [p('8. Backend API Overview','H1R'),p('The backend exposes REST endpoints under `/api`. The frontend default base URL is `http://localhost:8080/api`.'),table([['METHOD','ENDPOINT','PURPOSE'],['GET','/api/products','List products; optional search query.'],['POST','/api/products','Create product.'],['PUT','/api/products/{id}','Update product.'],['DELETE','/api/products/{id}','Delete product.'],['GET / POST','/api/suppliers','List or create supplier records.'],['PUT / DELETE','/api/suppliers/{id}','Update or delete a supplier.'],['GET','/api/transactions','List stock movement history.'],['POST','/api/transactions','Record stock IN/OUT and update quantity.'],['GET','/api/dashboard','Return KPIs and recent transactions.'],['GET','/api/reports/inventory.csv','Download inventory CSV.']],[25*mm,57*mm,CW-82*mm]),p('8.1 Example transaction payload','H2R'),Preformatted('{\n  "productId": 2,\n  "type": "OUT",\n  "quantity": 3\n}',S['CodeR']),p('A successful response contains the transaction ID, product ID and name snapshot, type, quantity, and timestamp. Stock-out requests above available quantity are rejected. The API does not yet provide a centralized error response format.'),PageBreak()]

