story += [p('10. Installation and Execution','H1R'),p('10.1 Prerequisites','H2R'),p('Node.js 18+ and npm; Java 17+; Maven 3.9+; PostgreSQL 14+ or Docker Desktop for the PostgreSQL deployment path.'),p('10.2 Start backend with local H2','H2R'),Preformatted('cd backend\nmvn spring-boot:run',S['CodeR']),p('The default file-backed H2 database is configured in `backend/src/main/resources/application.properties`. The backend listens on port 8080.'),p('10.3 Start frontend','H2R'),Preformatted('cd frontend\nnpm install\nnpm run dev',S['CodeR']),p('Open `http://localhost:5173`. Configure `VITE_API_URL` if the API is hosted elsewhere.'),p('10.4 Start PostgreSQL and backend with Docker','H2R'),Preformatted('docker compose up --build',S['CodeR']),p('Compose starts PostgreSQL and builds the backend container. The frontend remains a separate Vite process in the documented local workflow. For local backend runs, set the `SPRING_DATASOURCE_*` values from `.env.example`.'),callout('Environment configuration','The checked-in `.env.example` contains local demonstration credentials. Replace them with deployment-specific values before connecting to a shared database.'),PageBreak()]

# 11 Limits and conclusion
story += [p('11. Limitations and Future Enhancements','H1R'),p('11.1 Current limitations','H2R'),p('• Authentication and user roles are not implemented.<br/>• Forms have minimal validation; backend request validation is not applied consistently.<br/>• Controllers access repositories directly; service and DTO layers are absent.<br/>• Transactions store product ID as a scalar, not an enforced foreign key.<br/>• Suppliers are not linked to products, purchase orders, or replenishment.<br/>• PostgreSQL configuration exists but live connectivity was not verified.<br/>• When the API is offline, the UI shows fallback sample data; offline edits are not persisted to the backend.<br/>• Reporting is limited to an inventory CSV; there are no movement trends or supplier analytics.'),p('11.2 Future enhancements','H2R'),p('• Add Spring Security authentication and role-based access.<br/>• Separate controller, service, repository, entity, and DTO responsibilities; add consistent validation and error responses.<br/>• Add enforced product-transaction relationships, audit user identity, and transaction pagination.<br/>• Associate suppliers with products and add purchase orders and replenishment workflows.<br/>• Add automated API/UI tests and verify PostgreSQL persistence through Compose.<br/>• Expand reports with date filters, movement summaries, and warehouse/location support.'),p('12. Conclusion','H1R'),p('RIMS provides a working foundation for retail inventory operations: product and supplier management, quantity thresholds, stock movement recording, dashboard summaries, and CSV export. The application was built and exercised locally with H2 sample data. Its documented PostgreSQL setup and clearly stated limitations provide a basis for academic review and continued development.'),p('References','H2R'),p('[1] Spring Boot Reference Documentation: https://docs.spring.io/spring-boot/<br/>[2] Spring Data JPA Reference Documentation: https://docs.spring.io/spring-data/jpa/reference/<br/>[3] PostgreSQL Documentation: https://www.postgresql.org/docs/<br/>[4] React Documentation: https://react.dev/<br/>[5] Vite Documentation: https://vite.dev/<br/>[6] User-supplied Student Analyzer report; referenced for presentation structure and visual style, not project-specific facts.','SM')]

